type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const clone = (v: any): any => JSON.parse(JSON.stringify(v));
  const out = clone(d.value);
  for (const p of d.patches) {
    let n = out;
    for (const k of p.path.slice(0, -1)) n = n[k];
    const k = p.path.at(-1);
    if (p.op === "remove") delete n[k];
    else n[k] = clone(p.value);
  }
  return out;
}
